/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(NDXKBVRequestLine), DataEventType::Deleted)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void NDXKBVRequestLine_onDeleted(Common sender, DataEventArgs e)
{
    NDXBVEMailRequestLine nDXBVEMailRequestLine = NDXBVEMailRequestLine::findFromNDXKBVRequestLine(sender as NDXKBVRequestLine, true);
    if (nDXBVEMailRequestLine)
    {
        nDXBVEMailRequestLine.NDXKBVRequestLine = 0;
        ttsbegin;
        nDXBVEMailRequestLine.update();
        ttscommit;
    }
}
